data class Imported(val nodes:List<Node>,val width:Float,val height:Float)
object SvgImport {
    fun parseOwnSize(b:ByteArray,s:Double):Imported {
        val size=(960*s).toFloat()
        return Imported(listOf(Node(newId(),NodeKind.PATH,"icon",0f,0f,size,size,path=b.decodeToString())),size,size)
    }
}
